// 3D model of the right carotid triangle from Z-Anatomy meshes (CC BY-SA 4.0,
// based on BodyParts3D), plus paths drawn for this app where Z-Anatomy has no
// model (lingual artery, ansa cervicalis, superior thyroid and superior
// laryngeal arteries, superior laryngeal nerve). Geometry lives in
// data/carotid-meshes.js, generated by tools/export_zanatomy.py. Coordinates
// are centimetres centred on the carotid bifurcation: +y = superior,
// +z = anterior, and the patient's right side is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.carotid = {
  // Default view: the right side of the neck, head turned away, as at carotid surgery.
  camera: { target: [-0.6, 0.6, 0.6], radius: 22, theta: -1.2, phi: 1.62 },

  // [theta, phi] for the view buttons. The right side faces -x.
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-1.1, 2.5],
    anterior: [-0.1, 1.6]
  },

  // Starting axial level (0 = bottom of the model, 1 = top): just below the bifurcation.
  sectionLevel: 0.27,

  look: {
    mandible: { kind: "bone" },
    temporal: { kind: "bone" },
    hyoid: { kind: "bone" },
    larynx: { kind: "cartilage" },
    vertebrae: { kind: "bone", opacity: 0.6 },
    scm: { kind: "muscle", color: 0xa4423f },
    digastric: { kind: "muscle" },
    stylohyoid: { kind: "muscle", color: 0x9c3a3c },
    omohyoid: { kind: "muscle", color: 0xa13f3d },
    sternohyoid: { kind: "muscle", color: 0xa4423f },
    thyrohyoid: { kind: "muscle", color: 0x9a3c3c },
    hyoglossus: { kind: "muscle", color: 0x943a3b },
    mylohyoid: { kind: "muscle", color: 0x9a3c3c },
    constrictors: { kind: "muscle", color: 0x8f3739 },
    platysma: { kind: "muscle", color: 0xc2685a, opacity: 0.35 },
    smg: { kind: "gland", color: 0xd8a06a },
    parotid: { kind: "gland", color: 0xd9a46e },
    thyroid: { kind: "gland", color: 0xa8423a, opacity: 0.8 },
    triangle: { kind: "cartilage", color: 0x7fb8e6, opacity: 0.25 },
    cca: { kind: "artery" },
    ica: { kind: "artery" },
    eca: { kind: "artery" },
    facial_artery: { kind: "artery" },
    occipital_artery: { kind: "artery" },
    ascending_pharyngeal: { kind: "artery" },
    lingual_artery: { kind: "artery" },
    superior_thyroid_artery: { kind: "artery" },
    superior_laryngeal_artery: { kind: "artery" },
    ijv: { kind: "vein" },
    facial_vein: { kind: "vein" },
    lingual_vein: { kind: "vein" },
    superior_thyroid_vein: { kind: "vein" },
    retromandibular: { kind: "vein" },
    ejv: { kind: "vein" },
    vagus: { kind: "nerve" },
    hypoglossal: { kind: "nerve" },
    accessory: { kind: "nerve" },
    glossopharyngeal: { kind: "nerve" },
    sympathetic: { kind: "nerve", color: 0xd9c27a },
    ansa_cervicalis: { kind: "nerve" },
    sln: { kind: "nerve" },
    ebsln: { kind: "nerve" },
    nodes_ii: { kind: "node", color: 0x3fb6a8 },
    nodes_iii: { kind: "node", color: 0x4f8fdc }
  },

  build(THREE, h) {
    return h.fromMeshes("carotid", this.look);
  }
};
